import json
import logging
from collections.abc import Callable
from typing import Union, Dict, Tuple, Any, Optional

from elasticsearch import UnsupportedProductError
from elasticsearch.helpers.vectorstore import DenseVectorScriptScoreStrategy, DenseVectorStrategy, DistanceMetric as ESDistanceMetric, RetrievalStrategy
from langchain_core.documents import Document
from langchain_elasticsearch import ElasticsearchStore

from dataiku.core.vector_stores.dku_vector_store import DkuRemoteVectorStore, DistanceMetric, logger
from dataiku.core.vector_stores.vector_store_document_filter import DKU_SECURITY_TOKEN_META_PREFIX, VectorStoreDocumentFilter, ColumnType
from dataiku.langchain.metadata_generator import DKU_SECURITY_TOKENS_META
from dataiku.llm.types import RetrievableKnowledge, BaseVectorStoreQuerySettings
from dataikuapi.dss.admin import DSSConnectionInfo
from dataikuapi.dss.langchain import DKUEmbeddings


class ElasticSearchVectorStore(DkuRemoteVectorStore):
    DEFAULT_REQUIRED_FIELD_NAMES = {
        "content": "text",
        "vector": "vector",
    }

    def __init__(self, kb: RetrievableKnowledge, exec_folder: str, connection_info_retriever: Callable[[str], DSSConnectionInfo]):
        self.elasticsearch_url: str = ""
        self.auth_kwargs: Dict = {}
        self.version: Tuple[int, int] = (0, 0)
        super(ElasticSearchVectorStore, self).__init__(kb, exec_folder, connection_info_retriever)
        self.document_filter = ElasticSearchVectorStoreDocumentFilter(
            self.metadata_column_type_and_meaning,
            use_metadata_prefix=self.kb.get("managed", True),
        )

    def set_index_name(self, index_name: str) -> None:
        self.index_name = index_name.lower()

    def init_connection(self) -> None:
        connection_params = self.connection_info_retriever(self.connection_name).get_params()
        auth_type = connection_params['authType']
        self.auth_kwargs = {}
        scheme = "http"
        if connection_params['ssl']:
            scheme = "https"
            if connection_params['trustAnySSLCertificate']:
                self.auth_kwargs['es_params'] = {'verify_certs': False}

        self.elasticsearch_url = "{}://{}:{}".format(scheme, connection_params['host'], connection_params['port'])
        if auth_type == "NONE":
            pass
        elif auth_type == "PASSWORD":
            self.auth_kwargs['es_user'] = connection_params['username']
            self.auth_kwargs['es_password'] = connection_params['password']
        elif auth_type == "OAUTH2_APP":
            raise NotImplementedError("OAuth v2.0 is not supported for Knowledge Banks")
        elif auth_type in ["AWS_KEYPAIR", "AWS_ENVIRONMENT", "AWS_STS", "AWS_CUSTOM"]:
            # This error will be caught by the VectorStoreFactory and trigger the use of OpenSearch implementation instead
            raise UnsupportedProductError("'{}' authentication is only supported with OpenSearch".format(auth_type), {},{"version": {"distribution": "opensearch"}})
        else:
            raise ValueError("Unknown authentication type: " + auth_type)

        self.version = self.get_version()

    def get_rrf_settings(self, query_settings: BaseVectorStoreQuerySettings) -> Union[Dict, bool]:
        advanced_reranking = query_settings.get("useAdvancedReranking", False)
        if advanced_reranking:
            k = self._get_search_kwargs(query_settings)["k"]
            return {
                "rank_constant": query_settings.get("rrfRankConstant", 60),
                "rank_window_size": query_settings.get("rrfRankWindowSize", k)
            }
        return False

    def _get_db_kwargs(self, query_settings: BaseVectorStoreQuerySettings) -> Dict:
        hybrid = query_settings.get("searchType") == "HYBRID"
        rrf_settings = self.get_rrf_settings(query_settings)
        if hybrid and self.version < (8, 4):
            raise ValueError("Hybrid search is only supported with ElasticSearch v8.4+")
        if self.version < (8, 16) and rrf_settings:
            raise ValueError("RRF is only supported with ElasticSearch v8.16+")
        strategy = self.get_strategy(hybrid, rrf_settings)
        return {"strategy": strategy}

    def _get_search_kwargs(self, query_settings: BaseVectorStoreQuerySettings) -> Dict:  # type: ignore[override]
        search_kwargs = super()._get_search_kwargs(query_settings)
        field_names = self._get_required_field_names()
        metadata_columns = list(self.metadata_column_type_and_meaning.keys())
        requested_fields = [field_names["content"], "metadata", "metadata.*"] + metadata_columns + [
            "metadata.{}".format(column_name) for column_name in metadata_columns
        ]
        requested_fields = [field_name for field_name in dict.fromkeys(requested_fields) if field_name]

        def _custom_query(query_body: Dict[str, Any], query: Optional[str]) -> Dict[str, Any]:
            body = dict(query_body)
            body["_source"] = True
            body["fields"] = requested_fields
            return body

        if len(requested_fields) > 0:
            search_kwargs["fields"] = requested_fields
            search_kwargs["custom_query"] = _custom_query
        search_kwargs["doc_builder"] = self._build_document_from_hit(field_names)
        return search_kwargs

    @staticmethod
    def _get_search_type(query_settings: BaseVectorStoreQuerySettings) -> str:
        search_type = query_settings.get("searchType")
        if search_type == "HYBRID":
            search_type = "SIMILARITY"
        return DkuRemoteVectorStore.dss_search_type_to_langchain_search_type(search_type)

    def include_similarity_score(self, query_settings: BaseVectorStoreQuerySettings) -> bool:
        search_type = query_settings.get("searchType")
        return super().include_similarity_score(query_settings) and search_type != "HYBRID"

    def get_db(self, embeddings: Optional[DKUEmbeddings], allow_creation: bool = False, **kwargs: Any) -> ElasticsearchStore:
        """
        Instantiate the ElasticsearchStore db object

        :param embeddings: embeddings used to create the vector store
        :param allow_creation:  unused
        :param kwargs: if the `strategy` is provided, it will be used to instantiate the db object instead of the default one
        :rtype: ElasticsearchStore
        """
        # todo should check if index already exist to raise an error if allow_creation=false first (langchain always create it by default if unfound)

        # Enforce correct strategy instantiation if none present in kwargs
        kwargs["strategy"] = kwargs.get("strategy", self.get_strategy())
        field_names = self._get_required_field_names()

        db = ElasticsearchStore(
            es_url=self.elasticsearch_url,
            index_name=self.index_name,
            embedding=embeddings,
            query_field=field_names["content"],
            vector_query_field=field_names["vector"],
            **{**self.auth_kwargs, **kwargs}
        )
        return db

    def _get_result_metadata_fields(self) -> list[str]:
        field_names = self._get_required_field_names()
        excluded_fields = {
            field_names.get("id"),
            field_names.get("content"),
            field_names.get("vector"),
            "metadata",
        }
        return [
            column_name
            for column_name in self.metadata_column_type_and_meaning.keys()
            if column_name not in excluded_fields
        ]

    def _get_result_source_includes(self) -> list[str]:
        return [
            include
            for field in self._get_result_metadata_fields()
            for include in (field, f"metadata.{field}")
        ]

    @staticmethod
    def _extract_source_field(source: Dict[str, Any], field_name: Optional[str]) -> Any:
        if field_name is None:
            return None
        if field_name in source:
            value = source.get(field_name)
            if isinstance(value, list) and len(value) == 1:
                return value[0]
            return value
        current: Any = source
        for key in field_name.split("."):
            if not isinstance(current, dict) or key not in current:
                return None
            current = current.get(key)
        if isinstance(current, list) and len(current) == 1:
            return current[0]
        return current

    @staticmethod
    def _extract_fields_field(fields: Dict[str, Any], field_name: Optional[str]) -> Any:
        if field_name is None or not isinstance(fields, dict) or field_name not in fields:
            return None
        value = fields.get(field_name)
        if isinstance(value, list) and len(value) == 1:
            return value[0]
        return value

    @staticmethod
    def _get_first_non_none(*values: Any) -> Any:
        for value in values:
            if value is not None:
                return value
        return None

    def _extract_metadata_from_hit(self, source: Dict[str, Any], fields: Dict[str, Any], field_names: Dict[str, Optional[str]]) -> Dict[str, Any]:
        metadata_container = self._extract_source_field(source, "metadata")
        if not isinstance(metadata_container, dict):
            metadata_container = None

        metadata = {}
        for column_name in self.metadata_column_type_and_meaning.keys():
            value = self._get_first_non_none(
                self._extract_source_field(source, column_name),
                self._extract_fields_field(fields, column_name),
                self._extract_source_field(source, "metadata.{}".format(column_name)),
                self._extract_fields_field(fields, "metadata.{}".format(column_name)),
                self._extract_source_field(metadata_container, column_name) if isinstance(metadata_container, dict) else None,
            )
            if value is not None:
                metadata[column_name] = value

        if len(metadata) == 0 and isinstance(metadata_container, dict):
            metadata = metadata_container
        elif len(metadata) == 0:
            excluded_fields = {field_names["content"], field_names["vector"], field_names["id"], "metadata"}
            metadata = {k: v for k, v in source.items() if k not in excluded_fields}
        return metadata

    def _build_document_from_hit(self, field_names: Dict[str, Optional[str]]) -> Callable[[Dict[str, Any]], Document]:
        def _doc_builder(hit: Dict[str, Any]) -> Document:
            source = hit.get("_source")
            if not isinstance(source, dict):
                source = {}

            fields = hit.get("fields")
            if not isinstance(fields, dict):
                fields = {}

            content = self._get_first_non_none(
                self._extract_source_field(source, field_names["content"]),
                self._extract_fields_field(fields, field_names["content"]),
            )
            page_content = content if isinstance(content, str) else ("" if content is None else str(content))
            document_id = self._get_first_non_none(
                self._extract_source_field(source, field_names["id"]),
                self._extract_fields_field(fields, field_names["id"]),
                hit.get("_id"),
            )
            metadata = self._extract_metadata_from_hit(source, fields, field_names)
            return Document(id=document_id, page_content=page_content, metadata=metadata)

        return _doc_builder

    def get_strategy(self, hybrid: bool = False, rrf: Union[Dict, bool] = False) -> RetrievalStrategy:
        distance_strategy = self.get_distance_strategy()
        # ES versions < v8.4 does not support the KNN query (default strategy used in `ElasticsearchStore`),
        # so we need to use a less efficient strategy based on custom script scoring
        if self.version < (8, 4):
            logger.info("Using DenseVectorScriptScoreStrategy instead of KNN query params.")
            return DenseVectorScriptScoreStrategy(distance=distance_strategy)
        elif not self.kb.get("managed", True) and not hybrid and not rrf:
            logger.info("Using DenseVectorScriptScoreStrategy for unmanaged Elasticsearch index.")
            return DenseVectorScriptScoreStrategy(distance=distance_strategy)
        else:
            return DenseVectorStrategy(hybrid=hybrid, distance=distance_strategy, rrf=rrf)

    def get_distance_strategy(self) -> ESDistanceMetric:
        if self.distance_metric == DistanceMetric.DOT_PRODUCT:
            return getattr(ESDistanceMetric, "MAX_INNER_PRODUCT", ESDistanceMetric.DOT_PRODUCT)
        elif self.distance_metric == DistanceMetric.EUCLIDEAN:
            return ESDistanceMetric.EUCLIDEAN_DISTANCE
        else:
            return ESDistanceMetric.COSINE

    def get_version(self) -> Tuple[int, int]:
        # We retrieve the db first so that we get a chance to raise an UnsupportedProductError
        # that will be caught by the VectorStoreFactory if we are connecting to an OpenSearch
        db = ElasticsearchStore(index_name=self.index_name, es_url=self.elasticsearch_url, **self.auth_kwargs)
        try:
            version_number = db.client.info()["version"]["number"]
            logger.info("Connected to ElasticSearch v{}".format(version_number))
            v = version_number.split(".")
            return int(v[0]), int(v[1])
        # Reraise the exception as a ConnectionError
        except Exception as e:
            raise ConnectionError("Could not retrieve ElasticSearch version: {}".format(e))

    def clear_index(self) -> None:
        self.get_db(None).client.indices.delete(
            index=self.index_name,
            ignore_unavailable=True,
            allow_no_indices=True
        )
        logger.info("Cleared ElasticSearch index {}".format(self.index_name))


class ElasticSearchVectorStoreDocumentFilter(VectorStoreDocumentFilter):
    """ ElasticSearch document filter

    See https://www.elastic.co/guide/en/elasticsearch/reference/current/query-filter-context.html#filter-context
    and https://python.langchain.com/docs/integrations/vectorstores/elasticsearch/#query-vector-store
    """

    def __init__(self, metadata_column_type_and_meaning: Dict, use_metadata_prefix: bool = True):
        super().__init__(metadata_column_type_and_meaning)
        self.use_metadata_prefix = use_metadata_prefix

    def _field_path(self, column: str, keyword: bool = False) -> str:
        field_path = f"metadata.{column}" if self.use_metadata_prefix else column
        return f"{field_path}.keyword" if keyword else field_path

    def _string_equals_clause(self, column: str, value: str) -> Dict:
        if self.use_metadata_prefix:
            return {"match": {self._field_path(column, keyword=True): value}}
        return {
            "bool": {
                "should": [
                    {"term": {self._field_path(column, keyword=True): value}},
                    {"term": {self._field_path(column): value}},
                ],
                "minimum_should_match": 1,
            }
        }

    def _string_not_equals_clause(self, column: str, value: str) -> Dict:
        if self.use_metadata_prefix:
            return {"bool": {"must_not": {"match": {self._field_path(column, keyword=True): value}}}}
        return {
            "bool": {
                "must_not": [
                    {"term": {self._field_path(column, keyword=True): value}},
                    {"term": {self._field_path(column): value}},
                ]
            }
        }

    def _string_in_any_of_clause(self, column: str, values: list[str]) -> Dict:
        if self.use_metadata_prefix:
            return {"bool": {"should": [{"match": {self._field_path(column, keyword=True): value}} for value in values]}}
        return {
            "bool": {
                "should": (
                    [{"term": {self._field_path(column, keyword=True): value}} for value in values]
                    + [{"terms": {self._field_path(column): values}}]
                ),
                "minimum_should_match": 1,
            }
        }

    def _string_in_none_of_clause(self, column: str, values: list[str]) -> Dict:
        if self.use_metadata_prefix:
            return {"bool": {"must_not": [{"match": {self._field_path(column, keyword=True): value}} for value in values]}}
        return {
            "bool": {
                "must_not": (
                    [{"term": {self._field_path(column, keyword=True): value}} for value in values]
                    + [{"terms": {self._field_path(column): values}}]
                )
            }
        }

    def convert(self, clause: Dict) -> Dict:
        if clause["operator"] == "EQUALS":
            column_type = self._get_column_type(clause)
            if column_type in [ColumnType.String, ColumnType.BagOfWords]:
                return self._string_equals_clause(clause["column"], self._coerce_value(clause))
            elif column_type in [ColumnType.Decimal, ColumnType.Integer] or clause["column"].startswith(DKU_SECURITY_TOKEN_META_PREFIX):
                return {"term": {self._field_path(clause["column"]): self._coerce_value(clause)}}
            else:
                raise self._unsupported_type_for_operator(column_type, clause['operator'])
        elif clause["operator"] == "NOT_EQUALS":
            column_type = self._get_column_type(clause)
            if column_type in [ColumnType.String, ColumnType.BagOfWords]:
                return self._string_not_equals_clause(clause["column"], self._coerce_value(clause))
            elif column_type in [ColumnType.Decimal, ColumnType.Integer]:
                return {"bool": {"must_not": {"term": {self._field_path(clause["column"]): self._coerce_value(clause)}}}}
            else:
                raise self._unsupported_type_for_operator(column_type, clause['operator'])
        elif clause["operator"] == "GREATER_THAN":
            return {"range": {self._field_path(clause["column"]): {"gt": self._coerce_value(clause)}}}
        elif clause["operator"] == "LESS_THAN":
            return {"range": {self._field_path(clause["column"]): {"lt": self._coerce_value(clause)}}}
        elif clause["operator"] == "GREATER_OR_EQUAL":
            return {"range": {self._field_path(clause["column"]): {"gte": self._coerce_value(clause)}}}
        elif clause["operator"] == "LESS_OR_EQUAL":
            return {"range": {self._field_path(clause["column"]): {"lte": self._coerce_value(clause)}}}
        elif clause["operator"] == "IN_ANY_OF":
            column_type = self._get_column_type(clause)
            if column_type in [ColumnType.String, ColumnType.BagOfWords]:
                return self._string_in_any_of_clause(clause["column"], self._coerce_value(clause))
            elif column_type in [ColumnType.Decimal, ColumnType.Integer]:
                return {"terms": {self._field_path(clause["column"]): self._coerce_value(clause)}}
            else:
                raise self._unsupported_type_for_operator(column_type, clause['operator'])
        elif clause["operator"] == "IN_NONE_OF":
            column_type = self._get_column_type(clause)
            if column_type in [ColumnType.String, ColumnType.BagOfWords]:
                return self._string_in_none_of_clause(clause["column"], self._coerce_value(clause))
            elif column_type in [ColumnType.Decimal, ColumnType.Integer]:
                return {"bool": {"must_not": {"terms": {self._field_path(clause["column"]): self._coerce_value(clause)}}}}
            else:
                raise self._unsupported_type_for_operator(column_type, clause['operator'])
        elif clause["operator"] == "AND":
            return {"bool": {"filter": [self.convert(x) for x in clause["clauses"]]}}
        elif clause["operator"] == "OR":
            return {"bool": {"should": [self.convert(x) for x in clause["clauses"]]}}
        else:
            raise Exception("Unsupported filter operator for ElasticSearch: %s" % clause["operator"])

    def _and_filter(self, converted_clause_a: Dict, converted_clause_b: Dict) -> Dict:
        return {"bool": {"filter": [converted_clause_a, converted_clause_b]}}

    def _get_filter_field_name(self) -> str:
        return "filter"

    def add_security_tokens_to_document(self, document: Document) -> Document:
        """ Add a boolean field per token
        """
        if DKU_SECURITY_TOKENS_META in document.metadata:
            security_tokens = json.loads(document.metadata[DKU_SECURITY_TOKENS_META])
            for token in security_tokens:
                document.metadata[self._get_security_token_with_prefix(token)] = "true"
            logging.info("Updated metadata to %s" % self._sanitize_metadata_for_print(document.metadata))
        return document

    def _get_security_token_check_clause(self, token: str) -> Dict:
        return {
            "operator": "EQUALS",
            "column": self._get_security_token_with_prefix(token),
            "value": "true",
        }

    @staticmethod
    def _get_security_token_with_prefix(token: str) -> str:
        return DKU_SECURITY_TOKEN_META_PREFIX + token
